"use client"
import { useState } from "react"
import "../styles/Payments.css"

export default function Payment() {
  const [currentModal, setCurrentModal] = useState(null)
  const [selectedPlan, setSelectedPlan] = useState(null)
  const [selectedDuration, setSelectedDuration] = useState("1")
  const [formData, setFormData] = useState({ name: "", phone: "", email: "" })
  const [paymentMethod, setPaymentMethod] = useState("vnpay") // ✅ mặc định VNPay
  const [paymentData, setPaymentData] = useState(null)

  const plans = [
    { id: "pretinum", name: "Pretinum", price: 5000000, description: "Nâng cấp tài khoản cao cấp", buttonText: "Nâng cấp ngay" },
  ]

  const openModal = (step, plan) => {
    if (plan) setSelectedPlan(plan)
    setCurrentModal(step)
  }
  const closeModal = () => setCurrentModal(null)

  const formatPrice = (price) => price.toLocaleString("vi-VN") + "đ"

  const getPaymentAmount = () => {
    if (!selectedPlan) return 0
    return selectedPlan.price * parseInt(selectedDuration)
  }

  // 🔥 Gọi API backend để tạo link thanh toán
  const handlePayment = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/payment/create", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          amount: getPaymentAmount(),
          planId: selectedPlan?.id,
          duration: selectedDuration,
          customer: formData,
          method: paymentMethod, // ✅ VNPay / Momo / ZaloPay
        }),
      })

      const data = await res.json()
      setPaymentData(data)

      if (data.paymentUrl) {
        window.location.href = data.paymentUrl // redirect tới VNPay sandbox
      } else {
        alert("Không tạo được giao dịch!")
      }
    } catch (err) {
      console.error(err)
      alert("Lỗi khi tạo giao dịch!")
    }
  }

  const PaymentModal = () => (
    <div className="modal-overlay" onClick={closeModal}>
      <div className="modal-content payment-modal" onClick={(e) => e.stopPropagation()}>
        <button className="modal-close" onClick={closeModal}>×</button>
        <h2>Chọn phương thức thanh toán</h2>

        <div className="payment-methods">
          <label>
            <input
              type="radio"
              name="method"
              value="vnpay"
              checked={paymentMethod === "vnpay"}
              onChange={(e) => setPaymentMethod(e.target.value)}
            />
            VNPay (Thẻ nội địa / QR)
          </label>
          <label>
            <input
              type="radio"
              name="method"
              value="momo"
              checked={paymentMethod === "momo"}
              onChange={(e) => setPaymentMethod(e.target.value)}
            />
            Momo
          </label>
          <label>
            <input
              type="radio"
              name="method"
              value="zalopay"
              checked={paymentMethod === "zalopay"}
              onChange={(e) => setPaymentMethod(e.target.value)}
            />
            ZaloPay
          </label>
        </div>

        <div className="summary">
          <p><strong>Gói:</strong> {selectedPlan?.name}</p>
          <p><strong>Thời hạn:</strong> {selectedDuration} năm</p>
          <p><strong>Tổng tiền:</strong> {formatPrice(getPaymentAmount())}</p>
        </div>

        <button className="btn-pay" onClick={handlePayment}>
          Thanh toán ngay →
        </button>
      </div>
    </div>
  )

  return (
    <div className="payment-panel">
      <h1>Chọn gói nâng cấp</h1>
      <div className="plans-grid">
        {plans.map((plan) => (
          <div key={plan.id} className="plan-card">
            <h3>{plan.name}</h3>
            <p>{plan.description}</p>
            <p className="price">{formatPrice(plan.price)}/năm</p>
            <button onClick={() => openModal("payment", plan)}>{plan.buttonText}</button>
          </div>
        ))}
      </div>

      {currentModal === "payment" && <PaymentModal />}
    </div>
  )
}
